text(await tools.exec_command({workdir:"E:\\TA Projects\\EOD Charting Platform",cmd:`$paths = rg --files --hidden --no-ignore backups -g config.toml -g package.json -g Invoke-EOD-SharedCargo.ps1 -g prepare-tauri-portable.ps1
foreach ($file in '.cargo\\config.toml','package.json','scripts\\Invoke-EOD-SharedCargo.ps1','scripts\\prepare-tauri-portable.ps1') {
  "=== $file"
  $matches = @($paths | Where-Object { $_.EndsWith("\\$file") } | Sort-Object -Descending)
  "Copies: $($matches.Count)"
  foreach ($copy in @($matches | Select-Object -First 2) + @($matches | Select-Object -Last 1) | Select-Object -Unique) {
    $same = (Get-FileHash -LiteralPath $file).Hash -eq (Get-FileHash -LiteralPath $copy).Hash
    "$copy same=$same"
    Select-String -LiteralPath $copy -Pattern 'CARGO_TARGET_DIR|target-dir|tauri:portable:win|tauri:build' | ForEach-Object {$_.Line.Trim()}
  }
}
git log -4 -p -- .cargo/config.toml
git log --all -5 -S 'CARGO_TARGET_DIR' --oneline -- scripts package.json .cargo`,max_output_tokens:1600}))

text(await tools.exec_command({workdir:"E:\\TA Projects\\EOD Charting Platform",cmd:`$archives = Get-ChildItem -LiteralPath 'E:\\TA Projects\\EOD Charting Platform Source Audit' -Filter 'Eod Charting Platform Source Code*.zip' | Sort-Object Name -Descending | Select-Object -First 2
foreach ($archive in $archives) {
  $archive.Name
  $zip = [IO.Compression.ZipFile]::OpenRead($archive.FullName)
  try {
    foreach ($path in '.cargo/config.toml','package.json','scripts/prepare-tauri-portable.ps1') {
      $entry = $zip.Entries | Where-Object { ($_.FullName.Replace('\\','/') -eq $path) -or ($_.FullName.Replace('\\','/').EndsWith("/$path")) } | Select-Object -First 1
      if (!$entry) { "Missing: $path"; continue }
      $reader = [IO.StreamReader]::new($entry.Open())
      try { $body = $reader.ReadToEnd() } finally { $reader.Dispose() }
      $same = $body -ceq (Get-Content -LiteralPath $path -Raw)
      "$($entry.FullName) text matches current: $same"
      $body -split '\\r?\\n' | Where-Object { $_ -match 'target-dir|CARGO_TARGET_DIR|tauri:portable:win|^\\s*"tauri:build"|^\\$(sourceExe|portableBase|portableName|portableRoot|portableExe)\\s*=' }
    }
  } finally { $zip.Dispose() }
}`,max_output_tokens:1400}))
